+fn bounded_read(path: &Path, limit: usize) -> Result<String> {
+    let bytes = if crate::vfs::is_in_memory() {
+        crate::vfs::read(path)?
+    } else {
+        let mut bytes = Vec::new();
+        std::fs::File::open(path)?.take(limit as u64 + 1).read_to_end(&mut bytes)?;
+        bytes
+    };
+    ensure!(bytes.len() <= limit, "comparison input exceeds {limit} bytes");
+    Ok(String::from_utf8(bytes)?)
